import java.io.*;
import java.util.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long q = nextLong();
        long[] a = new long[n], costs = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        for (int i = 0; i < n; i++) costs[i] = Math.max(0, nextLong() - a[i]);
        Arrays.sort(costs);
        // Pay for the cheapest subjects first.
        int answer = 0;
        for (long cost : costs) {
            if (cost > q) break;
            q -= cost;
            answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, q := nextInt(), nextInt()
	a, costs := make([]int, n), make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	for i := range costs {
		costs[i] = max(0, nextInt()-a[i])
	}
	slices.Sort(costs)
	// Pay for the cheapest subjects first.
	answer := 0
	for _, cost := range costs {
		if cost > q {
			break
		}
		q -= cost
		answer++
	}
	os.Stdout.WriteString(strconv.Itoa(answer) + "\n")
}
